import React, { useState } from "react";
import axios from "axios";
import "./global.css";

export default function CreateListing() {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [size, setSize] = useState("");
  const [image, setImage] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append("title", title);
    formData.append("description", description);
    formData.append("price", price);
    formData.append("size", size);
    formData.append("image", image);

    // add ownerId from logged-in user
    const user = localStorage.getItem("user");
    if (user) {
      const parsed = JSON.parse(user);
      if (parsed._id) formData.append("ownerId", parsed._id);
    }

    try {
      const res = await axios.post("http://localhost:5001/api/products/create", formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });

      alert("Product uploaded successfully!");
      console.log(res.data);

      // reset form
      setTitle("");
      setDescription("");
      setPrice("");
      setSize("");
      setImage(null);

    } catch (error) {
      console.error(error);
      alert("Upload failed");
    }
  };

  return (
    <div className="create">
      <h2>Create Listing</h2>
      <form onSubmit={handleSubmit}>

        <input type="file" onChange={(e) => setImage(e.target.files[0])} required />

        <input type="text" placeholder="Title"
          value={title} onChange={(e) => setTitle(e.target.value)} required />

        <textarea placeholder="Description"
          value={description} onChange={(e) => setDescription(e.target.value)} required />

        <input type="number" placeholder="Price"
          value={price} onChange={(e) => setPrice(e.target.value)} required />

        <input type="text" placeholder="Size"
          value={size} onChange={(e) => setSize(e.target.value)} required />

        <button type="submit">Upload Product</button>
      </form>
    </div>
  );
}
